using System.Diagnostics;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
[TestCategory("Telemetry")]
public class TelemetryEvals
{
    private static readonly ActivityListener s_listener = new()
    {
        ShouldListenTo = source => source.Name.StartsWith("Microsoft.Extensions.AI"),
        Sample = (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllDataAndRecorded,
        ActivityStopped = activity => ValidateSpan(activity)
    };

    private static readonly List<Activity> s_captured = [];

    [ClassInitialize]
    public static void Setup(TestContext _)
    {
        ActivitySource.AddActivityListener(s_listener);
    }

    [ClassCleanup]
    public static void Teardown()
    {
        s_listener.Dispose();
    }

    [TestMethod]
    public async Task ChatSpan_HasRequiredAttributes()
    {
        // Arrange & Act: invoke the agent via the AppHost
        s_captured.Clear();
        await InvokeAgentAsync("Hello, coach!");

        // Assert: verify telemetry spans were emitted with expected attributes
        var chatSpan = s_captured.FirstOrDefault(a => a.OperationName == "chat");
        Assert.IsNotNull(chatSpan, "Expected a 'chat' span to be emitted");
        Assert.AreEqual("openai", chatSpan.GetTagItem("gen_ai.system")?.ToString());
        Assert.AreEqual("gpt-4o-mini", chatSpan.GetTagItem("gen_ai.request.model")?.ToString());
    }

    [TestMethod]
    public async Task ChatSpan_RecordsTokenUsage()
    {
        s_captured.Clear();
        await InvokeAgentAsync("Give me a quick tip");

        var chatSpan = s_captured.FirstOrDefault(a => a.OperationName == "chat");
        Assert.IsNotNull(chatSpan);

        var inputTokens = chatSpan.GetTagItem("gen_ai.response.input_tokens");
        var outputTokens = chatSpan.GetTagItem("gen_ai.response.output_tokens");
        Assert.IsNotNull(inputTokens, "Expected input token count");
        Assert.IsNotNull(outputTokens, "Expected output token count");
    }

    private static async Task InvokeAgentAsync(string message)
    {
        // TODO: Wire up AppHost distributed app testing to invoke the coach agent
        await Task.CompletedTask;
    }

    private static void ValidateSpan(Activity activity)
    {
        s_captured.Add(activity);
    }
}

using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
[TestCategory("Quality")]
public class QualityEvals
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Setup(TestContext context)
    {
        s_config = new ReportingConfiguration(
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "quality-reports"),
            evaluators:
            [
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
                new CompletenessEvaluator(),
            ]);
    }

    [TestMethod]
    public async Task Scenario_GreetingResponse_IsRelevant()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(Scenario_GreetingResponse_IsRelevant));

        var response = await GetAgentResponseAsync("Hello, I need coaching on time management");

        scenario.AddTurn(
            request: "Hello, I need coaching on time management",
            modelResponse: response);

        await scenario.EvaluateAsync();

        var relevance = scenario.GetResult<RelevanceEvaluator>();
        Assert.IsTrue(relevance.Rating?.Value >= 3,
            $"Relevance rating {relevance.Rating?.Value} is below threshold");
    }

    [TestMethod]
    public async Task Scenario_ActionableFeedback_IsComplete()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(Scenario_ActionableFeedback_IsComplete));

        var response = await GetAgentResponseAsync(
            "I procrastinate a lot. Give me 3 concrete steps to improve.");

        scenario.AddTurn(
            request: "I procrastinate a lot. Give me 3 concrete steps to improve.",
            modelResponse: response);

        await scenario.EvaluateAsync();

        var completeness = scenario.GetResult<CompletenessEvaluator>();
        Assert.IsTrue(completeness.Rating?.Value >= 4,
            $"Completeness rating {completeness.Rating?.Value} is below threshold");
    }

    private static async Task<string> GetAgentResponseAsync(string message)
    {
        // TODO: Wire up AppHost distributed app testing to invoke the coach agent
        await Task.CompletedTask;
        return string.Empty;
    }
}

using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
[TestCategory("Compare")]
public class CompareEvals
{
    private static readonly string s_baselinePath =
        Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "Baselines");

    [TestMethod]
    public async Task Compare_GreetingResponse_SemanticallyConsistent()
    {
        var baseline = await LoadBaselineAsync("greeting.txt");
        var current = await GetAgentResponseAsync("Hello, I need coaching on time management");

        var similarity = ComputeSemanticSimilarity(baseline, current);
        Assert.IsTrue(similarity >= 0.85,
            $"Semantic similarity {similarity:F3} dropped below 0.85 threshold");
    }

    [TestMethod]
    public async Task Compare_ActionSteps_WithinTokenBudget()
    {
        var baseline = await LoadBaselineAsync("action_steps.json");
        var baselineMetrics = System.Text.Json.JsonSerializer.Deserialize<BaselineMetrics>(baseline);

        var (response, tokenUsage) = await GetAgentResponseWithMetricsAsync(
            "Give me 3 steps to stop procrastinating");

        // Token usage should not regress by more than 15%
        var threshold = baselineMetrics!.TokenUsage * 1.15;
        Assert.IsTrue(tokenUsage <= threshold,
            $"Token usage {tokenUsage} exceeds baseline {baselineMetrics.TokenUsage} by more than 15%");
    }

    [TestMethod]
    public async Task Compare_Latency_WithinP95Budget()
    {
        var baseline = await LoadBaselineAsync("latency.json");
        var baselineMetrics = System.Text.Json.JsonSerializer.Deserialize<BaselineMetrics>(baseline);

        var sw = System.Diagnostics.Stopwatch.StartNew();
        await GetAgentResponseAsync("Quick tip for focus");
        sw.Stop();

        var threshold = baselineMetrics!.LatencyP95Ms * 1.15;
        Assert.IsTrue(sw.ElapsedMilliseconds <= threshold,
            $"Latency {sw.ElapsedMilliseconds}ms exceeds P95 baseline {baselineMetrics.LatencyP95Ms}ms by more than 15%");
    }

    private static async Task<string> LoadBaselineAsync(string filename)
    {
        var path = Path.Combine(s_baselinePath, filename);
        if (!File.Exists(path))
            return string.Empty;
        return await File.ReadAllTextAsync(path);
    }

    private static async Task<string> GetAgentResponseAsync(string message)
    {
        // TODO: Wire up AppHost distributed app testing to invoke the coach agent
        await Task.CompletedTask;
        return string.Empty;
    }

    private static async Task<(string Response, int TokenUsage)> GetAgentResponseWithMetricsAsync(string message)
    {
        // TODO: Wire up AppHost distributed app testing to invoke the coach agent
        await Task.CompletedTask;
        return (string.Empty, 0);
    }

    private static double ComputeSemanticSimilarity(string baseline, string current)
    {
        // TODO: Use embedding-based similarity; placeholder returns 1.0
        if (string.IsNullOrEmpty(baseline) || string.IsNullOrEmpty(current))
            return 1.0;
        return 1.0;
    }

    private record BaselineMetrics(int TokenUsage = 0, double LatencyP95Ms = 0);
}

