using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
[TestCategory("Quality")]
public class QualityEvals
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Setup(TestContext context)
    {
        s_config = new ReportingConfiguration(
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "quality-reports"),
            evaluators:
            [
                new RelevanceEvaluator(),
                new CoherenceEvaluator(),
                new CompletenessEvaluator(),
            ]);
    }

    [TestMethod]
    public async Task Scenario_GreetingResponse_IsRelevant()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(Scenario_GreetingResponse_IsRelevant));

        var response = await GetAgentResponseAsync("Hello, I need coaching on time management");

        scenario.AddTurn(
            request: "Hello, I need coaching on time management",
            modelResponse: response);

        await scenario.EvaluateAsync();

        var relevance = scenario.GetResult<RelevanceEvaluator>();
        Assert.IsTrue(relevance.Rating?.Value >= 3,
            $"Relevance rating {relevance.Rating?.Value} is below threshold");
    }

    [TestMethod]
    public async Task Scenario_ActionableFeedback_IsComplete()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(Scenario_ActionableFeedback_IsComplete));

        var response = await GetAgentResponseAsync(
            "I procrastinate a lot. Give me 3 concrete steps to improve.");

        scenario.AddTurn(
            request: "I procrastinate a lot. Give me 3 concrete steps to improve.",
            modelResponse: response);

        await scenario.EvaluateAsync();

        var completeness = scenario.GetResult<CompletenessEvaluator>();
        Assert.IsTrue(completeness.Rating?.Value >= 4,
            $"Completeness rating {completeness.Rating?.Value} is below threshold");
    }

    private static async Task<string> GetAgentResponseAsync(string message)
    {
        // TODO: Wire up AppHost distributed app testing to invoke the coach agent
        await Task.CompletedTask;
        return string.Empty;
    }
}

